mapper.update:
UPDATE sync_tasks
SET enabled= #{enabled} , updated_at=datetime( 'now' )
WHERE id= #{id}

mapper.sql:
WHERE id IN ( SELECT t.id FROM sync_tasks t JOIN el_resource_owners o ON o.resource_type='sync-task' AND o.resource_id=t.id AND o.owner_user_id=#{ownerId} LEFT JOIN el_resource_owners ds_owner ON ds_owner.resource_type='datasource' AND ds_owner.resource_id=t.data_source_id AND ds_owner.owner_user_id=#{ownerId} LEFT JOIN data_sources d ON d.id=ds_owner.resource_id WHERE 1=1
AND LOCATE(#{word}, LOWER(CONCAT_WS(' ', t.name, t.description, d.name, d.code, d.description, t.source_object, t.remote_path, t.file_pattern, t.target_db, t.target_table))) > 0
)

mapper.select:
SELECT t.id AS task_id, d.name AS data_source_name, d.type AS data_source_type, c.name AS connection_name, cp.state_json AS checkpoint_json, EXISTS(SELECT 1 FROM sync_runs q WHERE q.task_id=t.id AND q.status='queued') AS queued FROM sync_tasks t JOIN el_resource_owners o ON o.resource_type='sync-task' AND o.resource_id=t.id AND o.owner_user_id=#{ownerId} LEFT JOIN el_resource_owners ds_owner ON ds_owner.resource_type='datasource' AND ds_owner.resource_id=t.data_source_id AND ds_owner.owner_user_id=#{ownerId} LEFT JOIN data_sources d ON d.id=ds_owner.resource_id LEFT JOIN connections c ON c.id=t.connection_id LEFT JOIN sync_checkpoints cp ON cp.task_id=t.id
WHERE t.id IN #{taskId}
WHERE 1=0

SELECT t.id AS task_id,
       EXISTS(SELECT 1 FROM sync_runs q WHERE q.task_id=t.id AND q.status='queued') AS queued
FROM sync_tasks t
JOIN el_resource_owners o ON o.resource_type='sync-task' AND o.resource_id=t.id AND o.owner_user_id=#{ownerId}


        WHERE t.id IN #{taskId}

    WHERE 1=0
